void block_write(const char* buf, int offset, int size) {
  char page[PAGE_SIZE];
  int first = offset / PAGE_SIZE;
  int last  = (offset + size) / PAGE_SIZE;
  for (int p = first; p <= last; ++p) {
    int pstart = p * PAGE_SIZE;
    int from = std::max(offset, pstart);
    int to   = std::min(offset + size, pstart + PAGE_SIZE);
    page_read(p, page);
    std::memcpy(page + (from - pstart), buf + (from - offset), to - from);
    page_flush(p);
    page_write(p, page, PAGE_SIZE);
  }
}

size_t Ring::write(const char* src, size_t n) {
  size_t space = cap - count;
  if (n > space) n = space;
  size_t first = std::min(n, cap - head);
  std::memcpy(buf + head, src, first);
  std::memcpy(buf, src, n - first);
  head = (head + n) % cap;
  count += n;
  return n;
}
